11	
12	// Stable non-cryptographic hash so a filler building keeps the same look
13	// every run without City needing to know about models.
14	std::size_t stableHash(const std::string& s) {
15	    std::size_t h = 1469598103934665603ull;  // FNV-1a
16	    for (unsigned char c : s) {
17	        h ^= c;
18	        h *= 1099511628211ull;
19	    }
20	    return h;
21	}
22	
23	}  // namespace
24	
25	Assets::Assets(const std::string& assetsDir) {
26	    // Mood emotes are procedural — baked here regardless of downloads.
27	    for (int i = 0; i < 6; ++i) {
28	        faces_[i] = FaceTexture::bake(static_cast<NpcFace>(i));
29	    }
30	
31	    cityDir_ = assetsDir + "/models/city";
32	    charDir_ = assetsDir + "/models/characters";
33	    if (!std::filesystem::exists(cityDir_ + "/citybits_texture.png")) {
34	        std::cerr << "[llm_npc] assets/models missing — run tools/fetch_assets.sh "
35	                     "for the full look (drawing primitive shapes meanwhile)\n";
36	        return;
37	    }
38	
39	    // Landmarks: hand-picked silhouettes so each named spot reads distinctly.
40	    curated_ = {
41	        {"bakery", "building_A"},   {"police", "building_E"},
42	        {"coffee", "building_B"},   {"library", "building_D"},
43	        {"hardware", "building_C"}, {"office_a", "building_F"},
44	        {"tower", "building_H"},    {"taxi_cab", "car_taxi"},
45	        {"bench", "bench"},         {"cart", "box_B"},
46	        // No "fountain" entry: the pack has no fountain model, so the
47	        // renderer composes one from primitives (drawFountain), taking its
48	        // height from the SizeSpec below. An entry here would draw a model
49	        // instead and skip the composite.
50	        {"trafficlight_a", "trafficlight_A"}, {"trafficlight_b", "trafficlight_A"},
51	        {"trafficlight_c", "trafficlight_A"}, {"trafficlight_d", "trafficlight_A"},
52	        {"bush_a", "bush"}, {"bush_b", "bush"},
53	        {"bush_c", "bush"}, {"bush_d", "bush"},
54	        {"police_car", "car_police"},
