111	Assets::~Assets() {
112	    for (Texture2D& face : faces_) UnloadTexture(face);
113	    for (auto& [stem, model] : models_) UnloadModel(model);
114	    for (auto& character : characters_) {
115	        if (character.clips) UnloadModelAnimations(character.clips, character.clipCount);
116	        UnloadModel(character.model);
117	    }
118	}
119	
120	void Assets::loadCharacter(const std::string& stem) {
121	    const std::string path = charDir_ + "/" + stem + ".glb";
122	    if (!std::filesystem::exists(path)) {
123	        std::cerr << "[llm_npc] missing character: " << path << "\n";
124	        return;
125	    }
126	    CharacterAsset character;
127	    character.model = LoadModel(path.c_str());
128	    if (character.model.meshCount == 0) {
129	        std::cerr << "[llm_npc] failed to load character: " << path << "\n";
130	        return;
131	    }
132	
133	    // The packs mix skinned body meshes with unskinned attachment meshes
134	    // (held items). raylib 5.5's CPU skinning dereferences boneWeights
135	    // unconditionally and crashes on the unskinned ones, so compact them
136	    // out — v1 characters simply don't show hand props.
137	    int kept = 0;
138	    for (int i = 0; i < character.model.meshCount; ++i) {
139	        if (character.model.meshes[i].boneWeights != nullptr) {
140	            character.model.meshes[kept] = character.model.meshes[i];
141	            character.model.meshMaterial[kept] = character.model.meshMaterial[i];
142	            ++kept;
143	        } else {
144	            UnloadMesh(character.model.meshes[i]);
145	        }
146	    }
147	    character.model.meshCount = kept;
148	    if (kept == 0) {
149	        std::cerr << "[llm_npc] character had no skinned meshes: " << path << "\n";
150	        UnloadModel(character.model);
151	        return;
152	    }
153	
154	    character.clips = LoadModelAnimations(path.c_str(), &character.clipCount);
155	    for (int i = 0; i < character.clipCount; ++i) {
156	        const std::string name = character.clips[i].name;
157	        if (name == "Idle") character.idle = i;
158	        else if (name == "Walking_A") character.walk = i;
159	        else if (name == "Cheer") character.gesture = i;
160	        else if (name == "Death_A_Pose") character.death = i;
161	    }
162	    if (stem == "Knight") knightIndex_ = static_cast<int>(characters_.size());
163	    characters_.push_back(character);
164	}
165	
166	const Assets::CharacterAsset* Assets::characterFor(int variantSeed, bool police) const {
167	    if (characters_.empty()) return nullptr;
168	    if (police && knightIndex_ >= 0) return &characters_[static_cast<std::size_t>(knightIndex_)];
169	    return &characters_[static_cast<std::size_t>(variantSeed) % characters_.size()];
170	}
